const rss_feeds = [
  "https://hnrss.org/frontpage",
  "https://www.nasa.gov/rss/dyn/breaking_news.rss"
];

const topics = [
  "ai safety",
  "model context protocol",
  "n8n automation",
  "vector databases",
  "prompt injection"
];

const config = {
  cache_ttl_minutes: 45,
  dedupe_ttl_days: 10,
  min_score: 5,
  max_items_total: 30,
  enable_llm_summary: true,
  ZAI_API_KEY: $env.ZAI_API_KEY || "",
  ZAI_BASE_URL: $env.ZAI_BASE_URL || "https://api.z.ai/api/paas/v4",
  ZAI_MODEL: $env.ZAI_MODEL || "glm-5"
};

return [{ json: { rss_feeds, topics, config } }];

const items = $input.all();
const results = [];
const feedUrl = items[0]?.json?.rss_url || '';

const sourceMap = {
  "hnrss.org": "hackernews",
  "nasa.gov": "nasa"
};

let source = "rss";
for (const [key] of Object.entries(sourceMap)) {
  if (feedUrl.includes(key)) source = sourceMap[key];
}

for (const item of items) {
  const data = item.json;
  results.push({
    json: {
      source: source,
      topic: null,
      title: data.title || "Untitled",
      url: data.link || data.guid || "",
      published_at: data.pubDate || data.isoDate || new Date().toISOString(),
      raw_score: 0,
      score: 5,
      summary_raw: data.contentSnippet || data.description || null,
      summary: null,
      meta: {
        author: data.creator || data.author || null,
        venue: source,
        cached: false
      }
    }
  });
}

return results;

const topic = $json.topic;
const config = $('Init').first().json.config;
const st = $getWorkflowStaticData('global');

if (!st.cache) st.cache = {};

const now = Date.now();
const ttl_ms = config.cache_ttl_minutes * 60 * 1000;

// Prune expired cache entries
for (const k in st.cache) {
  if (now - st.cache[k].ts_epoch_ms > ttl_ms) {
    delete st.cache[k];
  }
}

const cached = st.cache[topic];
if (cached && (now - cached.ts_epoch_ms < ttl_ms)) {
  return [{ json: { topic, config, cache_hit: true, cached_items: cached.items || [] } }];
}

return [{ json: { topic, config, cache_hit: false, cached_items: [] } }];

const items = $json.cached_items || [];
if (items.length === 0) {
  return [{ json: { __empty: true, __stream: 'cache', __meta: { cached_hits: 0 } } }];
}
return items.map(i => ({ json: { ...i, meta: { ...i.meta, cached: true }, __meta: { cached_hits: items.length } } }));

const data = $json;
const topic = $('Cache Gate').first().json.topic;
const items = [];

// Guard: check for valid response
if (!data || data.error || !data.items || !Array.isArray(data.items)) {
  return [{ json: { __empty: true, __src: 'stackoverflow', __meta: { failed_calls: 1 } } }];
}

for (const i of data.items) {
  items.push({
    json: {
      source: "stackoverflow",
      topic: topic,
      title: i.title || "Untitled",
      url: i.link || "",
      published_at: i.creation_date ? new Date(i.creation_date * 1000).toISOString() : null,
      raw_score: i.score || 0,
      score: (i.score || 0) + (i.answer_count || 0),
      summary_raw: i.excerpt || (i.tags ? i.tags.join(', ') : null),
      summary: null,
      meta: {
        author: i.owner?.display_name || null,
        venue: "StackOverflow",
        cached: false
      }
    }
  });
}

return items;

const data = $json;
const topic = $('Cache Gate').first().json.topic;
const items = [];

// Guard: check for valid response
if (!data || data.error || !data.message || !data.message.items) {
  return [{ json: { __empty: true, __src: 'crossref', __meta: { failed_calls: 1 } } }];
}

for (const i of data.message.items) {
  const title = (Array.isArray(i.title) ? i.title[0] : i.title) || "Untitled";
  const url = (i.URL && i.URL.startsWith('http')) ? i.URL : `https://doi.org/${i.DOI}`;
  const refs = i['is-referenced-by-count'] || 0;
  const dateParts = i.published?.['date-parts']?.[0];

  items.push({
    json: {
      source: "crossref",
      topic: topic,
      title: title,
      url: url,
      published_at: dateParts ? dateParts.join('-') : null,
      raw_score: refs,
      score: 20 + refs,
      summary_raw: i.abstract || null,
      summary: null,
      meta: {
        author: null,
        venue: i['container-title']?.[0] || "Journal",
        cached: false
      }
    }
  });
}

return items;

const topic = $('Cache Gate').first().json.topic;
const st = $getWorkflowStaticData('global');

// Ensure cache exists
if (!st.cache) st.cache = {};

// Collect valid items (skip __empty markers)
let failedCalls = 0;
const validItems = [];

for (const item of $input.all()) {
  const i = item.json;
  if (i.__empty) {
    if (i.__meta?.failed_calls) failedCalls += i.__meta.failed_calls;
    continue;
  }
  validItems.push(i);
}

// Save to cache (even if empty - prevents repeated API calls on no results)
st.cache[topic] = {
  ts_epoch_ms: Date.now(),
  items: validItems
};

// Return items with metadata
if (validItems.length === 0) {
  return [{ json: { __empty: true, topic, __meta: { api_calls: 2, failed_calls: failedCalls || 2 } } }];
}

return validItems.map(i => ({ json: { ...i, __meta: { api_calls: 2, failed_calls: 0 } } }));

const config = $('Init').first().json.config;
const st = $getWorkflowStaticData('global');

if (!st.seen) st.seen = {};

const now = Date.now();
const dedupe_ms = config.dedupe_ttl_days * 24 * 60 * 60 * 1000;

// Prune old seen entries to prevent unbounded growth
for (const k in st.seen) {
  if (now - st.seen[k] > dedupe_ms) delete st.seen[k];
}

const allItems = $input.all();
const stats = {
  candidates_total: 0,
  new_items: 0,
  cached_hits: 0,
  api_calls: 0,
  failed_calls: 0,
  by_source: {}
};

const final = [];

for (const item of allItems) {
  const i = item.json;

  // Skip empty markers but count their stats
  if (i.__empty) {
    if (i.__meta?.failed_calls) stats.failed_calls += i.__meta.failed_calls;
    continue;
  }

  stats.candidates_total++;
  stats.by_source[i.source] = (stats.by_source[i.source] || 0) + 1;

  // Count cached hits
  if (i.meta?.cached) stats.cached_hits++;

  // Count API calls from metadata
  if (i.__meta?.api_calls) stats.api_calls += i.__meta.api_calls;
  if (i.__meta?.failed_calls) stats.failed_calls += i.__meta.failed_calls;

  // Dedupe and score filter
  if (i.url && !st.seen[i.url]) {
    if (i.score >= config.min_score) {
      final.push(i);
      st.seen[i.url] = now;
      stats.new_items++;
    }
  }
}

final.sort((a, b) => b.score - a.score);
const sliced = final.slice(0, config.max_items_total);

return [{ json: {
  config,
  stats,
  items: sliced,
  run_id: $workflow.id,
  generated_at: new Date().toISOString(),
  topics: $('Init').first().json.topics
} }];

const data = $json;
const topItems = (data.items || []).slice(0, 12);

const content = topItems.map(i => 
  `URL: ${i.url}\nTitle: ${i.title}\nRaw: ${i.summary_raw || ''}`
).join('\n\n');

return [{
  json: {
    // Preserve all original data - will be read by Apply Summaries
    __baseData: {
      config: data.config,
      stats: data.stats,
      items: data.items,
      run_id: data.run_id,
      generated_at: data.generated_at,
      topics: data.topics
    },
    // LLM request payload
    llm_payload: {
      model: data.config.ZAI_MODEL,
      messages: [{
        role: "user",
        content: `Summarize the following items into a JSON object with key 'summaries', an array of objects with 'url' and 'summary' (max 20 words).\n\n${content}`
      }],
      temperature: 0.3
    },
    config: data.config
  }
}];

// Get base data from Prepare LLM node (preserves context after HTTP overwrites)
const prepNode = $('Prepare LLM').first().json;
const baseData = prepNode.__baseData || prepNode;

// Get LLM response from current input (HTTP response)
const llmResponse = $input.first().json;

let summariesMap = {};

try {
  const content = llmResponse?.choices?.[0]?.message?.content;
  if (content) {
    const parsed = JSON.parse(content);

    // Format 1: { summaries: [{ url, summary }, ...] }
    if (Array.isArray(parsed.summaries)) {
      for (const s of parsed.summaries) {
        if (s.url && s.summary) {
          summariesMap[s.url] = s.summary;
        }
      }
    }
    // Format 2: { "<url>": "<summary>", ... }
    else if (typeof parsed === 'object') {
      for (const [url, summary] of Object.entries(parsed)) {
        if (typeof summary === 'string') {
          summariesMap[url] = summary;
        }
      }
    }
  }
} catch (e) {
  console.error('LLM response parse error:', e);
}

// Apply summaries to items
const items = (baseData.items || []).map(i => ({
  json: {
    ...i,
    summary: summariesMap[i.url] || i.summary_raw || i.title
  }
}));

return [{ json: {
  config: baseData.config,
  stats: baseData.stats,
  items: items.map(i => i.json),
  run_id: baseData.run_id,
  generated_at: baseData.generated_at,
  topics: baseData.topics
} }];

const data = $json;
const items = (data.items || []).map(i => ({
  json: {
    ...i,
    summary: i.summary_raw || i.title
  }
}));

return [{ json: {
  config: data.config,
  stats: data.stats,
  items: items.map(i => i.json),
  run_id: data.run_id,
  generated_at: data.generated_at,
  topics: data.topics
} }];

const data = $json;

if (!Array.isArray(data.items)) {
  throw new Error('Invalid: items must be array');
}

for (const i of data.items) {
  if (!i.url || typeof i.url !== 'string') {
    throw new Error('Invalid: missing or invalid url');
  }
  if (typeof i.score !== 'number') {
    throw new Error('Invalid: score must be number');
  }
  // Check for unresolved mustache templates
  const s = JSON.stringify(i);
  if (s.includes('{{') && s.includes('}}')) {
    throw new Error('Invalid: unresolved mustache template detected');
  }
}

return [{ json: data }];

const data = $json;
const groups = {};

for (const i of data.items) {
  if (!groups[i.source]) groups[i.source] = [];
  groups[i.source].push(i);
}

let md = `# PulseMosaic Digest - ${data.generated_at}\n\n`;
md += `**Topics:** ${data.topics?.join(', ') || 'N/A'}\n\n`;
md += `**Stats:** ${data.stats?.new_items || 0} new items, ${data.stats?.cached_hits || 0} cached, ${data.stats?.api_calls || 0} API calls\n\n`;

for (const [src, items] of Object.entries(groups)) {
  md += `## ${src.toUpperCase()}\n`;
  for (const i of items) {
    md += `- [${i.title}](${i.url}) (Score: ${i.score})\n`;
    if (i.summary) md += `  > ${i.summary}\n`;
  }
  md += `\n`;
}

return [{ json: { ...data, digest_markdown: md } }];
